const input = require("fs").readFileSync(0, "utf8");

function findStartStation(gas, cost) {
  let total = 0; // fuel left after the whole circle
  let tank = 0; // fuel left since the current start
  let start = 0;
  for (let i = 0; i < gas.length; i++) {
    total += gas[i] - cost[i];
    tank += gas[i] - cost[i];
    if (tank < 0) {
      // No station from start to i can be the start, so try the next one.
      start = i + 1;
      tank = 0;
    }
  }
  return total >= 0 ? start : -1;
}

