#include <iostream>
#include <vector>

int findStartStation(const std::vector<int>& gas, const std::vector<int>& cost) {
    int total = 0;  // fuel left after the whole circle
    int tank = 0;   // fuel left since the current start
    int start = 0;
    for (int i = 0; i < static_cast<int>(gas.size()); i++) {
        total += gas[i] - cost[i];
        tank += gas[i] - cost[i];
        if (tank < 0) {
            // No station from start to i can be the start, so try the next one.
            start = i + 1;
            tank = 0;
        }
    }
    return total >= 0 ? start : -1;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> gas(n);
    std::vector<int> cost(n);
    for (int i = 0; i < n; i++) {
        std::cin >> gas[i];
    }
    for (int i = 0; i < n; i++) {
        std::cin >> cost[i];
    }
    std::cout << findStartStation(gas, cost) << "\n";
